'use strict'

const { ipcRenderer } = require( 'electron' )
const i18n			= require( './i18n.min' )
const path 			= require('path')
const fs 			= require( 'fs-extra' )
const log			= require( 'electron-log' )



module.exports.importBookmarks = function() {
	
	ipcRenderer.invoke('show-open-dialog', {
			
		buttonLabel: i18n.t('import:opendialog.button', 'Import Bookmarks'),
		properties: [	'openFile'
					],
		filters: [
					{	name:		'HTML',
						extensions:	['html', 'htm']
					}
				]
		}
	).then((data) =>{
		
		if( !data.canceled && data.filePaths && data.filePaths.length > 0 ) {
			
			let filePath = data.filePaths[0]
			importFileToServer( filePath )
		}
	})
}



function importFileToServer( filePath ) {
	
	let fileName = path.basename( filePath )
	
	log.info( `import: reading file "${fileName}"…` )
	
	fs.readFile( filePath, 'utf8' )
	
	.then( content => {
		
		if( !content || content.trim().length === 0 ) {
			
			ipcRenderer.send('show-error-box', {
				title: i18n.t('import:errorbox.title', 'Import Error'),
				content: i18n.t('import:errorbox.empty', 'The selected file is empty.')
			})
			return
		}
		
		log.info( `import: sending file "${fileName}" to server (${content.length} bytes)…` )
		
		// Build credentials
		const Store		= require( 'electron-store' )
		const store		= new Store()
		
		let server 		= store.get( 'loginCredentials.server' ),
			username 	= store.get( 'loginCredentials.username' ),
			password 	= store.get( 'loginCredentials.password' )
		
		if( !server || !username || !password ) {
			
			ipcRenderer.send('show-error-box', {
				title: i18n.t('import:errorbox.title', 'Import Error'),
				content: 'Not logged in to Nextcloud.'
			})
			return
		}
		
		// Build FormData with the HTML file content
		// The Nextcloud Bookmarks API accepts:
		//   POST /public/rest/v2/folder/{folder_id}/import
		//   with multipart/form-data, field "bm_import" = HTML bookmark file content
		let formData = new FormData()
		formData.append( 'bm_import', new Blob([content], { type: 'text/html' }), fileName )
		
		let requestUrl = server + '/index.php/apps/bookmarks/public/rest/v2/folder/-1/import'
		
		log.info( `import: POST to ${requestUrl}` )
		
		fetch( requestUrl, {
			
			method: 'POST',
			headers: {
				'Authorization': 'Basic ' + btoa( username + ':' + password )
				// Note: no Content-Type set — fetch() auto-sets multipart/form-data with boundary
			},
			body: formData
			
		}).then( response => {
			
			log.info( `import: server responded ${response.status} ${response.statusText}` )
			
			if( response.ok ) {
				
				return response.text().then( body => {
					
					// Try to parse JSON response to show count
					let count = 'many'
					try {
						let json = JSON.parse(body)
						if( json && json.data && json.data.length ) {
							count = json.data.length
						}
					} catch(e) {}
					
					log.info( `import: successfully imported ${count} bookmarks from "${fileName}"` )
					
					// Show notification
					let notification = new Notification('Nextcloud Bookmark Manager', {
						body: i18n.t('import:notification.body', '{{count}} bookmarks imported from:\n{{- name}}', {count: count, name: fileName})
					})
					
					// Trigger refresh to show imported bookmarks
					ipcRenderer.send('import-complete', '')
				})
				
			} else {
				
				return response.text().then( body => {
					
					log.error( `import failed: ${response.status} - ${body}` )
					
					ipcRenderer.send('show-error-box', {
						title: i18n.t('import:errorbox.title', 'Import Error'),
						content: `Server returned ${response.status} ${response.statusText}\n\n${body || 'No details'}`
					})
				})
			}
			
		}).catch( error => {
			
			log.error( error )
			
			ipcRenderer.send('show-error-box', {
				title: i18n.t('import:errorbox.title', 'Import Error'),
				content: `Network error importing bookmarks:\n${error.message}`
			})
		})
	})
	
	.catch( error => {
		
		log.error( error )
		
		ipcRenderer.send('show-error-box', {
			title: i18n.t('import:errorbox.title', 'Import Error'),
			content: i18n.t('import:errorbox.readfile', 'An error occured reading the file:\n{{- filepath}}', {filepath: filePath})
		})
	})
}

